// One row per ICAO type designator, sorted by icao for ac_spec_find().
// Zero means "unknown" for every numeric field - render it as a dash,
// do not print a zero wingspan.
struct AcSpec {
  char icao[5];         // "B738"
  const char *mfr;      // "BOEING"
  const char *model;    // "737-800"
  const char *cls;      // "LandPlane" / "Helicopter" / ...
  uint8_t eng_n;        // engine count
  uint8_t eng_t;        // 1 piston 2 turboprop/shaft 3 jet 4 electric
  const char *eng;      // engine series, "CFM56" - no variant
  uint16_t span_dm;     // wingspan, 0.1 m
  uint16_t len_dm;      // length, 0.1 m
  uint16_t mtow_100kg;  // max take-off weight, 100 kg
  uint16_t cruise_kt;   // cruise TAS, kt
  int16_t sil;          // AC_SIL_A8 tile index, -1 = no drawing
};

