inline constexpr int AC_SPECS_LEN = 318;

// Binary search - AC_SPECS is sorted by icao.
inline const AcSpec *ac_spec_find(const char *ty) {
  if (ty == nullptr || *ty == 0) return nullptr;
  int lo = 0, hi = AC_SPECS_LEN - 1;
  while (lo <= hi) {
    int mid = (lo + hi) / 2;
    int c = strcmp(ty, AC_SPECS[mid].icao);
    if (c == 0) return &AC_SPECS[mid];
    if (c < 0) hi = mid - 1; else lo = mid + 1;
  }
  return nullptr;
}

// Fallback drawing when the type code is unknown: the ADS-B emitter
// category ("A3" = large, "A5" = heavy, "A7" = rotorcraft, ...) at
// least gets the size class right.  Index [letter A/B/C][0..7], -1 = none.
inline const int16_t AC_CAT_SIL[3][8] = {
  { -1, 65, 76, 58, 59, 61, 84, 52 },   // A0..A7
  { -1, 49, 2, 3, 4, -1, 5, 6 },   // B0..B7
  { -1, 0, 1, -1, -1, -1, -1, -1 },   // C0..C7
};
inline int16_t ac_cat_sil(const char *cat) {
  if (cat == nullptr || cat[0] == 0 || cat[1] == 0) return -1;
  int r = cat[0] - 'A', c = cat[1] - '0';
  if (r < 0 || r > 2 || c < 0 || c > 7) return -1;
  return AC_CAT_SIL[r][c];
}

