inline constexpr int AC_OPERATORS_LEN = 6004;
inline const AcOperator *ac_operator_find(const char *cs) {
  if (cs == nullptr) return nullptr;
  char k[4] = { 0, 0, 0, 0 };
  for (int i = 0; i < 3; i++) {
    if (cs[i] < 'A' || cs[i] > 'Z') return nullptr;   // 註冊號呼號不是三碼公司代碼
    k[i] = cs[i];
  }
  int lo = 0, hi = AC_OPERATORS_LEN - 1;
  while (lo <= hi) {
    int mid = (lo + hi) / 2;
    int c = strcmp(k, AC_OPERATORS[mid].code);
    if (c == 0) return &AC_OPERATORS[mid];
    if (c < 0) hi = mid - 1; else lo = mid + 1;
  }
  return nullptr;
}

