inline constexpr int AC_HEX_BLOCKS_LEN = 189;
inline const char *ac_country_find(uint32_t addr) {
  if (addr == 0) return nullptr;
  int lo = 0, hi = AC_HEX_BLOCKS_LEN - 1;
  while (lo <= hi) {
    int mid = (lo + hi) / 2;
    if (addr < AC_HEX_BLOCKS[mid].lo) hi = mid - 1;
    else if (addr > AC_HEX_BLOCKS[mid].hi) lo = mid + 1;
    else return AC_HEX_BLOCKS[mid].country;
  }
  return nullptr;
}
